package com.mo.economy_system.target.neoforge1211.protocol;
import com.mo.economy_system.common.network.*;import com.mo.economy_system.common.market.MarketOrderType;import com.mo.economy_system.platform.item.ItemStackSnapshotCodec;import io.netty.handler.codec.DecoderException;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.RegistryFriendlyByteBuf;import java.util.*;
final class NeoForge1211MarketDataCodec {
 static final NeoForge1211MessageCodec<MarketDataRequestMessage> REQUEST=new NeoForge1211MessageCodec<>(){public void encode(MarketDataRequestMessage m,RegistryFriendlyByteBuf b){b.writeLong(m.requestId());b.writeEnum(m.purpose());b.writeInt(m.offset());b.writeInt(m.limit());b.writeEnum(m.filter());b.writeUtf(m.query(),EconomyNetworkLimits.MAX_MARKET_QUERY_LENGTH);}public MarketDataRequestMessage decode(RegistryFriendlyByteBuf b){try{return new MarketDataRequestMessage(b.readLong(),readEnum(b,MarketDataRequestPurpose.values()),b.readInt(),b.readInt(),readEnum(b,MarketOrderFilter.values()),b.readUtf(EconomyNetworkLimits.MAX_MARKET_QUERY_LENGTH));}catch(RuntimeException e){throw new DecoderException("invalid market request",e);}}};
 static final NeoForge1211MessageCodec<MarketDataResponseMessage> RESPONSE=new NeoForge1211MessageCodec<>(){public void encode(MarketDataResponseMessage m,RegistryFriendlyByteBuf b){b.writeEnum(m.kind());b.writeLong(m.requestId());b.writeInt(m.offset());b.writeInt(m.limit());b.writeInt(m.totalMatched());b.writeInt(m.totalSales());b.writeInt(m.totalDemand());b.writeInt(m.orders().size());for(var o:m.orders())writeOrder(o,b);}public MarketDataResponseMessage decode(RegistryFriendlyByteBuf b){try{var k=readEnum(b,MarketDataResponseKind.values());long id=b.readLong();int off=b.readInt(),lim=b.readInt(),matched=b.readInt(),sales=b.readInt(),demand=b.readInt(),size=b.readInt();if(size<0||size>EconomyNetworkLimits.MAX_MARKET_PAGE_SIZE)throw new DecoderException("invalid count");List<MarketOrderSnapshot> os=new ArrayList<>(size);for(int i=0;i<size;i++)os.add(readOrder(b));return new MarketDataResponseMessage(k,id,off,lim,matched,sales,demand,os);}catch(RuntimeException e){if(e instanceof DecoderException d)throw d;throw new DecoderException("invalid response",e);}}};
 private static void writeOrder(MarketOrderSnapshot o,RegistryFriendlyByteBuf b){b.writeEnum(o.type());b.writeUUID(o.tradeId());b.writeNbt(ItemStackSnapshotCodec.encode(o.item()).orElseThrow());b.writeInt(o.quantity());b.writeInt(o.totalPrice());b.writeUtf(o.ownerName(),EconomyNetworkLimits.MAX_MARKET_OWNER_NAME_LENGTH);b.writeUUID(o.ownerId());b.writeLong(o.listingTime());b.writeLong(o.expirationTime());b.writeBoolean(o.delivered());}
 private static MarketOrderSnapshot readOrder(RegistryFriendlyByteBuf b){MarketOrderType t=readEnum(b,MarketOrderType.values());UUID id=b.readUUID();CompoundTag tag=b.readNbt();if(tag==null)throw new DecoderException("missing snapshot");return new MarketOrderSnapshot(t,id,ItemStackSnapshotCodec.decode(tag).orElseThrow(),b.readInt(),b.readInt(),b.readUtf(EconomyNetworkLimits.MAX_MARKET_OWNER_NAME_LENGTH),b.readUUID(),b.readLong(),b.readLong(),b.readBoolean());}
 private static <E>E readEnum(RegistryFriendlyByteBuf b,E[] values){int n=b.readVarInt();if(n<0||n>=values.length)throw new DecoderException("invalid enum");return values[n];}
}
